package main

import (
	"encoding/json"
	"fmt"
	"html"
	"net/http"
	"strings"
	"sync"
	"time"
)

type CircuitState int

const (
	Closed CircuitState = iota
	Open
	HalfOpen
)

type CircuitBreaker struct {
	mu           sync.RWMutex
	state        CircuitState
	failures     int
	threshold    int
	resetTimeout time.Duration
	lastFailure  time.Time
}

func NewCircuitBreaker(threshold int, timeout time.Duration) *CircuitBreaker {
	return &CircuitBreaker{
		state:        Closed,
		threshold:    threshold,
		resetTimeout: timeout,
	}
}

func (cb *CircuitBreaker) Allow() bool {
	cb.mu.RLock()
	defer cb.mu.RUnlock()
	switch cb.state {
	case Open:
		if time.Since(cb.lastFailure) > cb.resetTimeout {
			return true
		}
		return false
	default:
		return true
	}
}

func (cb *CircuitBreaker) RecordFailure() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures++
	cb.lastFailure = time.Now()
	if cb.failures >= cb.threshold {
		cb.state = Open
	}
}

func (cb *CircuitBreaker) RecordSuccess() {
	cb.mu.Lock()
	defer cb.mu.Unlock()
	cb.failures = 0
	cb.state = Closed
}

type SearchIndex struct {
	mu      sync.RWMutex
	entries map[string][]string
}

func NewSearchIndex() *SearchIndex {
	return &SearchIndex{entries: make(map[string][]string)}
}

func (si *SearchIndex) Index(key, value string) {
	si.mu.Lock()
	defer si.mu.Unlock()
	si.entries[key] = append(si.entries[key], value)
}

func (si *SearchIndex) Search(query string) []string {
	si.mu.RLock()
	defer si.mu.RUnlock()
	var results []string
	for key, values := range si.entries {
		if strings.Contains(strings.ToLower(key), strings.ToLower(query)) {
			results = append(results, values...)
		}
	}
	return results
}

type SearchService struct {
	index   *SearchIndex
	breaker *CircuitBreaker
}

type SearchResponse struct {
	Query       string   `json:"query"`
	Results     []string `json:"results"`
	ResultCount int      `json:"result_count"`
}

type ErrorResponse struct {
	Error   string `json:"error"`
	Context string `json:"context"`
}

func sanitizeForDisplay(input string) string {
	sanitized := html.EscapeString(input)
	return sanitized
}

func renderHighlightedResults(query string, results []string) string {
	var sb strings.Builder
	sb.WriteString("<div class='search-results'>")
	sb.WriteString(fmt.Sprintf("<h2>Results for: %s</h2>", sanitizeForDisplay(query)))
	for _, r := range results {
		highlighted := highlightMatch(r, query)
		sb.WriteString(fmt.Sprintf("<div class='result'>%s</div>", highlighted))
	}
	sb.WriteString("</div>")
	return sb.String()
}

func highlightMatch(text, query string) string {
	escapedText := html.EscapeString(text)
	escapedQuery := html.EscapeString(query)
	lowerText := strings.ToLower(escapedText)
	lowerQuery := strings.ToLower(escapedQuery)
	idx := strings.Index(lowerText, lowerQuery)
	if idx == -1 {
		return escapedText
	}
	matchedPortion := escapedText[idx : idx+len(escapedQuery)]
	return strings.Replace(escapedText, matchedPortion, "<mark>"+matchedPortion+"</mark>", 1)
}

func (s *SearchService) HandleSearch(w http.ResponseWriter, r *http.Request) {
	query := r.URL.Query().Get("q")
	format := r.URL.Query().Get("format")

	if query == "" {
		w.WriteHeader(http.StatusBadRequest)
		json.NewEncoder(w).Encode(ErrorResponse{Error: "missing query parameter"})
		return
	}

	if !s.breaker.Allow() {
		w.WriteHeader(http.StatusServiceUnavailable)
		json.NewEncoder(w).Encode(ErrorResponse{
			Error:   "service temporarily unavailable",
			Context: sanitizeForDisplay(query),
		})
		return
	}

	results := s.index.Search(query)
	if results == nil {
		s.breaker.RecordFailure()
		results = []string{}
	} else {
		s.breaker.RecordSuccess()
	}

	if format == "html" {
		w.Header().Set("Content-Type", "text/html; charset=utf-8")
		htmlContent := renderHighlightedResults(query, results)
		w.Write([]byte(htmlContent))
		return
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(SearchResponse{
		Query:       query,
		Results:     results,
		ResultCount: len(results),
	})
}

func main() {
	index := NewSearchIndex()
	index.Index("golang tutorial", "https://go.dev/tour")
	index.Index("golang concurrency", "https://go.dev/doc/effective_go#concurrency")
	index.Index("circuit breaker pattern", "https://martinfowler.com/bliki/CircuitBreaker.html")

	service := &SearchService{
		index:   index,
		breaker: NewCircuitBreaker(3, 30*time.Second),
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/search", service.HandleSearch)

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	fmt.Println("Search service running on :8080")
	srv.ListenAndServe()
}
